// One simulation step of a spiking layer with k-WTA inhibition (sketch).
for (const n of layer) {
  const ff = dot(n.wFF, input);            // proximal, feedforward
  const distal = n.segments.some(s => overlap(s, context) >= s.theta);
  n.vDend += dt / tauD * (-(n.vDend - EL) + (distal ? dendKick : 0));
  n.v += dt / tauM * (-(n.v - EL) + R * ff + gc * (n.vDend - n.v) - inhibition);
}
const fired = layer.filter(n => n.v >= vTh).sort((a, b) => b.v - a.v).slice(0, k);
for (const n of fired) { n.v = vReset; stdpUpdate(n, input); }
inhibition += wInh * fired.length - dt / tauI * inhibition;
